 using System.ComponentModel;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Configuration ---
 var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
 var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
 var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing 2026";

 Console.WriteLine($"Research Agent Starting — topic: \"{topic}\"");
 Console.WriteLine(new string('─', 60));

 // --- Notes store (shared state for the note-taking tool) ---
 var notes = new List<string>();

 // --- Tool definitions ---
 [Description("Search the web for a query and return relevant snippets.")]
 static string WebSearch([Description("The search query")] string query)
 {
     // In production, replace with a real search API (Bing, Google, Tavily, etc.)
     Console.WriteLine($"  🔍 [WebSearch] \"{query}\"");
     return $"""
         Search results for "{query}":
         1. "{query}" — Wikipedia summary: A comprehensive overview of the topic covering key concepts, history, and recent developments.
         2. Latest News: Researchers announce breakthroughs related to {query}, published in Nature and Science journals (2026).
         3. Academic paper: "Advances in {query}" — explores state-of-the-art techniques and future directions.
         """;
 }

 [Description("Save a research note for later use in the summary.")]
 string TakeNote([Description("The note content to save")] string note)
 {
     notes.Add(note);
     Console.WriteLine($"  📝 [TakeNote] saved note #{notes.Count}");
     return $"Note #{notes.Count} saved successfully.";
 }

 [Description("Retrieve all saved research notes.")]
 string GetNotes()
 {
     if (notes.Count == 0) return "No notes saved yet.";
     Console.WriteLine($"  📋 [GetNotes] returning {notes.Count} note(s)");
     return string.Join("\n\n", notes.Select((n, i) => $"Note #{i + 1}: {n}"));
 }

 // --- Build the chat client with tools ---
 IChatClient client = new OpenAIClient(openAiKey)
     .GetChatClient(model)
     .AsIChatClient()
     .AsBuilder()
     .UseFunctionInvocation()
     .Build();

 var chatOptions = new ChatOptions
 {
     Tools =
     [
         AIFunctionFactory.Create(WebSearch),
         AIFunctionFactory.Create(TakeNote),
         AIFunctionFactory.Create(GetNotes),
     ]
 };

 // --- Agent system prompt ---
 var messages = new List<ChatMessage>
 {
     new(ChatRole.System, """
         You are a research agent. Your job is to thoroughly research a given topic using the
         available tools, then produce a well-organized summary.

         Workflow:
         1. Use WebSearch multiple times with different queries to gather diverse information.
         2. Use TakeNote to record key findings as you go.
         3. Use GetNotes to review everything you've collected.
         4. Produce a final comprehensive summary with sections and citations.

         Be thorough — perform at least 3 different searches before summarizing.
         """),
     new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
 };

 // --- Run the agent loop ---
 var response = await client.GetResponseAsync(messages, chatOptions);

 Console.WriteLine();
 Console.WriteLine(new string('─', 60));
 Console.WriteLine("📄 RESEARCH SUMMARY");
 Console.WriteLine(new string('─', 60));
 Console.WriteLine(response.Text);
 Console.WriteLine(new string('─', 60));
 Console.WriteLine($"\nTotal notes collected: {notes.Count}");

